//! Time zones for EventBridge Scheduler: an IANA name, the POSIX TZ rule the zone follows now, and the arithmetic between a wall clock
//! reading and an instant.
//!
//! **Why a rule table and not a time zone database.** A schedule only asks about the future, and the future of a zone is its POSIX
//! rule (the footer of its TZif file). The table (`zones.rs`, generated by `tools/gen-tz-rules.ts` from tzdata) costs about 15 KB;
//! chrono-tz costs 1.2 MB and jiff's bundled database 400 KB (measured 2026-11-14 on a minimal binary built for size). Reading the
//! operating system's zoneinfo files would cost nothing but differs by machine and does not exist on Windows. The cost of the choice:
//! a zone whose government has announced a change that its current rule does not show is right only after the table is regenerated,
//! and an instant before a zone's last historical change is placed by today's rule (a `StartDate` years in the past, never a fire).

use crate::civil::{days_from_civil, days_in_month, weekday};
use crate::zones::{RULES, ZONES};

/// A time zone: its standard offset and, if it keeps one, its daylight saving time.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Zone {
    /// Seconds east of UTC in standard time.
    std: i32,
    dst: Option<Dst>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Dst {
    /// Seconds east of UTC in daylight saving time.
    off: i32,
    /// When it starts, in local standard time.
    start: Change,
    /// When it ends, in local daylight time.
    end: Change,
}

/// A day of the year and a time of that day (seconds, which may be negative or past a day).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Change {
    day: Day,
    secs: i32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Day {
    /// `Jn`: 1 to 365, never counting the 29th of February.
    NoLeap(u16),
    /// `n`: 0 to 365, counting it.
    Leap(u16),
    /// `Mm.w.d`: weekday `d` (0 is Sunday) of week `w` (5 is the last) of month `m`.
    Month(u8, u8, u8),
}

/// What a wall clock reading is in a zone.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Local {
    /// One instant (milliseconds since the epoch).
    Unique(i64),
    /// The clock skipped it (spring forward). The instant is where the reading lands when moved on by the length of the gap.
    Gap(i64),
    /// The clock showed it twice (fall back): the earlier and the later instant.
    Fold(i64, i64),
}

impl Zone {
    /// UTC.
    #[must_use]
    pub const fn utc() -> Self {
        Self { std: 0, dst: None }
    }

    /// The zone of an IANA name (`America/New_York`, `UTC`, `Asia/Kolkata`); `None` for a name the time zone database lacks.
    #[must_use]
    pub fn named(name: &str) -> Option<Self> {
        let i = ZONES.binary_search_by(|(n, _)| (*n).cmp(name)).ok()?;
        parse_rule(RULES.get(usize::from(ZONES.get(i)?.1))?)
    }

    /// Whether the time zone database knows the name.
    #[must_use]
    pub fn known(name: &str) -> bool {
        Self::named(name).is_some()
    }

    /// Seconds east of UTC at the instant.
    #[must_use]
    pub fn offset_at(&self, utc_ms: i64) -> i32 {
        let Some(d) = &self.dst else {
            return self.std;
        };
        let t = utc_ms.div_euclid(1000);
        let year = crate::civil::civil_from_days((t + i64::from(self.std)).div_euclid(86_400)).0;
        let start = d.start.local_secs(year) - i64::from(self.std);
        let end = d.end.local_secs(year) - i64::from(d.off);
        let in_dst = if start < end {
            start <= t && t < end
        } else {
            !(end <= t && t < start)
        };
        if in_dst { d.off } else { self.std }
    }

    /// The smallest offset the zone uses, in milliseconds: no instant after `t` reads earlier than `t` plus this on its clock.
    pub(crate) fn min_offset_ms(&self) -> i64 {
        let low = self.dst.as_ref().map_or(self.std, |d| d.off.min(self.std));
        i64::from(low) * 1000
    }

    /// The instant(s) a wall clock reading (milliseconds, counted as if the clock were UTC) stands for.
    #[must_use]
    pub fn resolve(&self, wall_ms: i64) -> Local {
        let Some(d) = &self.dst else {
            return Local::Unique(wall_ms - i64::from(self.std) * 1000);
        };
        let fits = |off: i32| {
            let t = wall_ms - i64::from(off) * 1000;
            (self.offset_at(t) == off).then_some(t)
        };
        match (fits(self.std), fits(d.off)) {
            (Some(a), Some(b)) if a != b => Local::Fold(a.min(b), a.max(b)),
            (Some(t), _) | (None, Some(t)) => Local::Unique(t),
            (None, None) => Local::Gap(wall_ms - i64::from(self.std.min(d.off)) * 1000),
        }
    }
}

impl Change {
    /// Seconds since the epoch, on a clock that reads local time as if it were UTC, when the change happens in `year`.
    fn local_secs(self, year: i64) -> i64 {
        let days = match self.day {
            Day::NoLeap(n) => {
                let n = i64::from(n);
                let skip = i64::from(crate::civil::leap(year) && n >= 60);
                days_from_civil(year, 1, 1) + n - 1 + skip
            }
            Day::Leap(n) => days_from_civil(year, 1, 1) + i64::from(n),
            Day::Month(m, w, d) => {
                let m = u32::from(m);
                let first = days_from_civil(year, m, 1);
                // `weekday` counts Sunday as 1; the rule counts it as 0.
                let first_dow = i64::from(weekday(first)) - 1;
                let mut day =
                    first + (i64::from(d) - first_dow).rem_euclid(7) + (i64::from(w) - 1) * 7;
                let last = first + i64::from(days_in_month(year, m)) - 1;
                while day > last {
                    day -= 7;
                }
                day
            }
        };
        days * 86_400 + i64::from(self.secs)
    }
}

/// Reads a POSIX TZ rule: `EST5EDT,M3.2.0,M11.1.0`, `<+0530>-5:30`, `IST-1GMT0,M10.5.0,M3.5.0/1`.
fn parse_rule(text: &str) -> Option<Zone> {
    let mut p = Cursor {
        s: text.as_bytes(),
        i: 0,
    };
    p.name()?;
    let std = -p.offset()?;
    if p.done() {
        return Some(Zone { std, dst: None });
    }
    p.name()?;
    let off = if p.peek().is_some_and(|c| c != b',') {
        -p.offset()?
    } else {
        std + 3600
    };
    let (start, end) = if p.eat(b',') {
        let start = p.change()?;
        if !p.eat(b',') {
            return None;
        }
        (start, p.change()?)
    } else {
        // POSIX's default: the United States' rule.
        (
            Change {
                day: Day::Month(3, 2, 0),
                secs: 7200,
            },
            Change {
                day: Day::Month(11, 1, 0),
                secs: 7200,
            },
        )
    };
    p.done().then_some(Zone {
        std,
        dst: Some(Dst { off, start, end }),
    })
}

struct Cursor<'a> {
    s: &'a [u8],
    i: usize,
}

impl Cursor<'_> {
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }

    fn done(&self) -> bool {
        self.i >= self.s.len()
    }

    fn eat(&mut self, c: u8) -> bool {
        let hit = self.peek() == Some(c);
        self.i += usize::from(hit);
        hit
    }

    fn name(&mut self) -> Option<()> {
        if self.eat(b'<') {
            while self.peek()? != b'>' {
                self.i += 1;
            }
            self.i += 1;
            return Some(());
        }
        let from = self.i;
        while self.peek().is_some_and(|c| c.is_ascii_alphabetic()) {
            self.i += 1;
        }
        (self.i - from >= 3).then_some(())
    }

    fn number(&mut self) -> Option<i32> {
        let from = self.i;
        while self.peek().is_some_and(|c| c.is_ascii_digit()) {
            self.i += 1;
        }
        std::str::from_utf8(self.s.get(from..self.i)?)
            .ok()?
            .parse()
            .ok()
    }

    /// `[+-]hh[:mm[:ss]]` as seconds.
    fn offset(&mut self) -> Option<i32> {
        let sign = if self.eat(b'-') {
            -1
        } else {
            self.eat(b'+');
            1
        };
        let mut secs = self.number()? * 3600;
        for scale in [60, 1] {
            if !self.eat(b':') {
                break;
            }
            secs += self.number()? * scale;
        }
        Some(sign * secs)
    }

    fn change(&mut self) -> Option<Change> {
        let day = if self.eat(b'M') {
            let m = self.number()?;
            self.eat(b'.').then_some(())?;
            let w = self.number()?;
            self.eat(b'.').then_some(())?;
            let d = self.number()?;
            Day::Month(
                u8::try_from(m).ok()?,
                u8::try_from(w).ok()?,
                u8::try_from(d).ok()?,
            )
        } else if self.eat(b'J') {
            Day::NoLeap(u16::try_from(self.number()?).ok()?)
        } else {
            Day::Leap(u16::try_from(self.number()?).ok()?)
        };
        let secs = if self.eat(b'/') { self.offset()? } else { 7200 };
        Some(Change { day, secs })
    }
}
